diff --git a/tests/runners/browser_test_runner_tests.js b/tests/runners/browser_test_runner_tests.js
index 00b20be..4386d5e 100644
--- a/tests/runners/browser_test_runner_tests.js
+++ b/tests/runners/browser_test_runner_tests.js
@@ -528,4 +528,37 @@ describe('browser test runner', function() {
       runner.finish();
     });
   });
+
+
+  describe('abort', function() {
+    let runner, reporter, socket, config;
+
+    beforeEach(function() {
+      reporter = new FakeReporter();
+      config = new Config('ci', { reporter: reporter });
+      let launcher = new Launcher('ci', { protocol: 'browser' }, config);
+      runner = new BrowserTestRunner(launcher, reporter, 1, true, config);
+      socket = new FakeSocket();
+      runner.socket = socket;
+    });
+
+    it('is idempotent and emits abort-tests via the socket', function() {
+      let emit = sinon.spy(socket, 'emit');
+      return Bluebird.all([runner.abort(), runner.abort()]).then(function() {
+        expect(emit).to.have.been.calledWith('abort-tests');
+        expect(emit).to.have.been.calledOnce();
+        expect(runner.aborted).to.be.true();
+      });
+    });
+
+    it('suppresses subsequent results and errors', function() {
+      runner.abort();
+      runner.onTestResult({ name: 'late', failed: 1 });
+      runner.onGlobalError('boom', 'url', 1);
+      runner.onProcessError(new Error('boom'));
+
+      expect(reporter.total).to.equal(0);
+    });
+  });
+
 });
diff --git a/tests/runners/process_test_runner_tests.js b/tests/runners/process_test_runner_tests.js
index 47f0250..2c46ad2 100644
--- a/tests/runners/process_test_runner_tests.js
+++ b/tests/runners/process_test_runner_tests.js
@@ -147,4 +147,46 @@ describe('ProcessTestRunner', function() {
       done();
     });
   });
+
+
+  describe('abort', function() {
+    let runner, reporter;
+
+    beforeEach(function() {
+      reporter = new FakeReporter();
+      let settings = { protocol: 'process' };
+      let config = new Config('ci', { reporter: reporter });
+      let launcher = new Launcher('proc', settings, config);
+      runner = new ProcessTestRunner(launcher, reporter);
+      runner.process = {
+        kill: function() { return Promise.resolve(); }
+      };
+      runner.onStart = function() {};
+      runner.onEnd = function() {};
+      runner.onFinish = function() {};
+    });
+
+    it('is idempotent and finishes without reporting results', function(done) {
+      let killCount = 0;
+      runner.process.kill = function() {
+        killCount++;
+        return Promise.resolve();
+      };
+      runner.abort().then(function() {
+        return runner.abort();
+      }).then(function() {
+        expect(killCount).to.equal(1);
+        expect(runner.finished).to.be.true();
+        expect(reporter.total).to.equal(0);
+        done();
+      }).catch(done);
+    });
+
+    it('suppresses process errors after abort', function() {
+      runner.abort();
+      runner.onProcessError(new Error('killed'));
+      expect(reporter.total).to.equal(0);
+    });
+  });
+
 });
